<?php

namespace App\Database\Seeds;

use CodeIgniter\Database\Seeder;

class WarhammerDataSeeder extends Seeder
{
    public function run()
    {
        $db = \Config\Database::connect();
        $sysBuilder = $db->table('rpg_systems');

        // 1. Pobierz ID systemu WFRP 2ed
        // Zakładamy, że RpgInitializationSeeder już go stworzył, ale dla bezpieczeństwa sprawdzamy.
        $systemCode = 'wfrp2ed';
        $system = $sysBuilder->where('code', $systemCode)->get()->getRow();
        
        if (!$system) {
            echo "⚠️ Nie znaleziono systemu '$systemCode'. Tworzę go awaryjnie...\n";
            $sysBuilder->insert([
                'code'        => $systemCode,
                'name'        => 'Warhammer Fantasy Roleplay 2ed',
                'description' => 'Ponury świat niebezpiecznych przygód.',
                'created_at'  => date('Y-m-d H:i:s')
            ]);
            $systemId = $db->insertID();
        } else {
            $systemId = $system->id;
        }

        echo "🔧 Importowanie szczegółowych danych (Skills/Talents) dla WFRP 2ed (ID: $systemId)...\n";

        // 2. Import Umiejętności
        $skills = $this->getWfrpSkills();
        $this->migrujKategorie($db, $systemId, 'umiejetnosc', $skills, function($row) {
            return [
                'name'        => $row[1],
                'description' => isset($row[4]) ? $row[4] : '',
                'metadata'    => json_encode([
                    'typ'       => isset($row[2]) ? $row[2] : 'Podstawowa',
                    'cecha'     => isset($row[3]) ? $row[3] : '',
                    'powiazane' => isset($row[5]) ? $row[5] : '',
                    'koszt_xp'  => isset($row[6]) ? $row[6] : 0,
                    'mechanika' => isset($row[7]) ? $row[7] : ''
                ])
            ];
        });

        // 3. Import Zdolności
        $talents = $this->getWfrpTalents();
        $this->migrujKategorie($db, $systemId, 'zdolnosc', $talents, function($row) {
            return [
                'name'        => $row[1],
                'description' => isset($row[2]) ? $row[2] : '',
                'metadata'    => json_encode([
                    'efekt'       => isset($row[3]) ? $row[3] : '',
                    'modyfikator' => isset($row[4]) ? $row[4] : '',
                    'talent'      => isset($row[5]) ? $row[5] : ''
                ])
            ];
        });
    }

    /**
     * Pomocnicza funkcja do importowania danych kategoriami.
     */
    private function migrujKategorie($db, $systemId, $category, $rows, $mapper)
    {
        $builder = $db->table('game_definitions');
        $count = 0;

        foreach ($rows as $row) {
            $data = $mapper($row);
            $data['system_id'] = $systemId;
            $data['category']  = $category;
            $data['created_at'] = date('Y-m-d H:i:s');

            // Sprawdzamy duplikaty po nazwie, systemie i kategorii
            $exists = $builder->where('system_id', $systemId)
                              ->where('category', $category)
                              ->where('name', $data['name'])
                              ->countAllResults();

            if ($exists == 0) {
                $builder->insert($data);
                $count++;
            }
        }
        echo "✅ Zaimportowano $count rekordów do kategorii: '$category'.\n";
    }

